begin;
set local search_path=public,extensions;
grant usage on schema extensions to authenticated;
select plan(7);
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)select('a2300000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','client-fiche-'||i||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,3)i;
insert into public.platform_user_roles(user_id,role_code)values('a2300000-0000-4000-8000-000000000001','MATRICIA_ADMIN');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b2300000-0000-4000-8000-000000000001','TEST Fiche client','TEST Fiche client','PENDING','a2300000-0000-4000-8000-000000000001');
insert into public.organization_memberships(organization_id,user_id,status)select'b2300000-0000-4000-8000-000000000001',('a2300000-0000-4000-8000-'||lpad(i::text,12,'0'))::uuid,'ACTIVE'from generate_series(1,3)i;
insert into public.client_compliance_cases(id,organization_id,status,created_by)values('f2300000-0000-4000-8000-000000000001','b2300000-0000-4000-8000-000000000001','DOCUMENTS_REQUIRED','a2300000-0000-4000-8000-000000000001');
insert into public.client_profile_versions(compliance_case_id,organization_id,version,profile_data,organization_snapshot,source_organization_row_version,created_by)values('f2300000-0000-4000-8000-000000000001','b2300000-0000-4000-8000-000000000001',1,'{"legal_form":"TEST SARL","activity":"TEST Conseil","registered_address":{"line1":"TEST Adresse"},"representative":{"email":"private-fiche-secret@example.invalid"}}','{"legal_name":"TEST Fiche client","country_code":"MA"}',1,'a2300000-0000-4000-8000-000000000001');
update public.client_compliance_cases set current_profile_version=1 where id='f2300000-0000-4000-8000-000000000001';
insert into public.client_administrative_anomalies(id,compliance_case_id,organization_id,anomaly_code,field_path,severity,blocking,status,client_message_fr,client_message_ar,detected_by)values('e2300000-0000-4000-8000-000000000001','f2300000-0000-4000-8000-000000000001','b2300000-0000-4000-8000-000000000001','ICE_NOT_VERIFIED','identifiers.ICE','CRITICAL',true,'OPEN','Vérifier les documents de cette identité de TEST','التحقق من وثائق هوية الاختبار','RULE_ENGINE');
create temporary table facts(v jsonb);grant all on facts to authenticated;
set local role authenticated;select set_config('request.jwt.claim.sub','a2300000-0000-4000-8000-000000000001',true);select set_config('request.jwt.claims','{"sub":"a2300000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
insert into facts values(public.get_admin_organization_fiche('b2300000-0000-4000-8000-000000000001'));
reset role;
select is((select jsonb_array_length(v->'memberships')from facts),3,'fixture has three actual memberships');
select is((select(v#>>'{organization,client_compliance_snapshot,document_count}')::int from facts),0,'document count is independent of memberships');
select is((select v#>>'{organization,client_legal_profile,legal_form}'from facts),'TEST SARL','legal form comes from actual current profile rather than Client classification');
select is((select v#>>'{organization,client_legal_profile,activity}'from facts),'TEST Conseil','activity comes from profile rather than display name');
select is((select(v#>>'{organization,client_compliance_snapshot,currently_verified}')::boolean from facts),false,'unfinished verification never displays completed KYC');
select is((select jsonb_array_length(v#>'{organization,client_compliance_snapshot,required_actions}')from facts),1,'real blocking anomaly appears in required actions');
select ok((select v::text not like'%private-fiche-secret%'from facts),'summary projection excludes representative personal contact');
select*from finish();rollback;
